-- Entasis Academy, migration 9 : schemas et figures des decks (brouillons).
--
-- Genere par scripts/academy/generer-decks.mjs depuis scripts/academy/decks/*.json :
-- ne pas editer a la main, regenerer. Complete le brouillon courant d un
-- module deja seme par la migration 7 : pose les schemas de la version
-- (remplacement par cle, les autres cles conservees), pose payload.figure
-- sur les exercices existants reperes par (ordre, type) qui n en ont pas
-- encore, insere les exercices nouveaux (ordre au dela du maximum existant)
-- avec leur corrige, ordre et association deja melanges. Idempotent. Une
-- version publiee n est jamais touchee : sans brouillon, raise notice et
-- rien. A appliquer apres la migration 8 (colonne academy_module_versions.schemas).

-- ── Schemas : Qualité du dossier et vigilance (qualite-du-dossier) ──
do $schemas_qualite_du_dossier$
declare v_mod uuid; v_ver uuid; v_max integer; v_item uuid; v_nouveaux jsonb; v_conserves jsonb;
begin
  select id into v_mod from public.academy_modules where slug = $academy_deck$qualite-du-dossier$academy_deck$;
  if v_mod is null then
    raise notice 'academy_9_schemas : module % absent, rien a faire (semer la migration 7 d abord)', $academy_deck$qualite-du-dossier$academy_deck$;
    return;
  end if;
  select id into v_ver from public.academy_module_versions where module_id = v_mod and statut = 'brouillon' order by numero desc limit 1;
  if v_ver is null then
    raise notice 'academy_9_schemas : aucun brouillon pour %, rien a faire (une version publiee ne se modifie pas)', $academy_deck$qualite-du-dossier$academy_deck$;
    return;
  end if;
  -- Schemas de la version : les cles du deck remplacent les leurs, les autres restent.
  v_nouveaux := $academy_deck$[{"cle":"trois_niveaux","titre":"Les trois niveaux de réaction","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 360\" font-family=\"system-ui, -apple-system, Segoe UI, sans-serif\">\n<title>Les trois niveaux de réaction</title>\n<rect x=\"0\" y=\"0\" width=\"640\" height=\"360\" fill=\"#FFFFFF\"/>\n<text x=\"320\" y=\"30\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"700\" fill=\"#162443\">Les trois niveaux de réaction</text>\n<g font-size=\"14\" fill=\"#8A95A8\" text-anchor=\"middle\">\n<text x=\"211\" y=\"62\">Ce que je vois</text>\n<text x=\"482\" y=\"62\">Ce que je fais</text>\n</g>\n<rect x=\"30\" y=\"70\" width=\"580\" height=\"74\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/>\n<rect x=\"30\" y=\"150\" width=\"580\" height=\"74\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<rect x=\"30\" y=\"230\" width=\"580\" height=\"74\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/>\n<g fill=\"#162443\">\n<circle cx=\"56\" cy=\"107\" r=\"15\"/>\n<circle cx=\"56\" cy=\"187\" r=\"15\"/>\n<circle cx=\"56\" cy=\"267\" r=\"15\"/>\n</g>\n<g font-size=\"14\" font-weight=\"700\" fill=\"#FFFFFF\" text-anchor=\"middle\">\n<text x=\"56\" y=\"112\">1</text>\n<text x=\"56\" y=\"192\">2</text>\n<text x=\"56\" y=\"272\">3</text>\n</g>\n<g stroke=\"#8A95A8\" stroke-width=\"2\">\n<line x1=\"346\" y1=\"82\" x2=\"346\" y2=\"132\"/>\n<line x1=\"346\" y1=\"162\" x2=\"346\" y2=\"212\"/>\n<line x1=\"346\" y1=\"242\" x2=\"346\" y2=\"292\"/>\n</g>\n<g font-size=\"15\" font-weight=\"700\" fill=\"#162443\">\n<text x=\"82\" y=\"96\">Pièce manquante</text>\n<text x=\"82\" y=\"176\">Opération inhabituelle</text>\n<text x=\"82\" y=\"256\">Soupçon</text>\n<text x=\"358\" y=\"96\">Réglé avec le client</text>\n<text x=\"358\" y=\"176\">Examen renforcé</text>\n<text x=\"358\" y=\"256\">Remontée écrite</text>\n</g>\n<g font-size=\"13\" fill=\"#2C3548\">\n<text x=\"82\" y=\"117\">ou écart explicable : adresse,</text>\n<text x=\"82\" y=\"135\">revenus, justificatif périmé</text>\n<text x=\"82\" y=\"197\">complexe, montant inhabituel,</text>\n<text x=\"82\" y=\"215\">sans logique économique</text>\n<text x=\"82\" y=\"277\">infraction punie de plus d’un an</text>\n<text x=\"82\" y=\"295\">d’emprisonnement, fraude fiscale</text>\n<text x=\"358\" y=\"117\">question neutre, réponse notée</text>\n<text x=\"358\" y=\"135\">avec sa date, sa source, sa pièce</text>\n<text x=\"358\" y=\"197\">origine et destination des fonds,</text>\n<text x=\"358\" y=\"215\">objet, bénéficiaire (L561-10-2)</text>\n<text x=\"358\" y=\"277\">au responsable, le jour même</text>\n<text x=\"358\" y=\"295\">puis Tracfin (L561-15), sur ERMES</text>\n</g>\n<rect x=\"30\" y=\"312\" width=\"580\" height=\"42\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"320\" y=\"331\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#162443\">Le conseiller ne déclare jamais : la personne habilitée le fait (R561-23).</text>\n<text x=\"320\" y=\"350\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Le client n’est jamais informé d’un signalement (L561-18).</text>\n</svg>","legende":"Le premier niveau se règle avec le client, le deuxième ouvre un examen renforcé, le troisième se remonte par écrit. Le conseiller ne déclare jamais lui même, et le client n’est jamais informé."},{"cle":"quatre_croisements","titre":"Les quatre croisements du dossier","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 360\" font-family=\"system-ui, -apple-system, Segoe UI, sans-serif\">\n<title>Les quatre croisements du dossier</title>\n<rect x=\"0\" y=\"0\" width=\"640\" height=\"360\" fill=\"#FFFFFF\"/>\n<text x=\"320\" y=\"30\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"700\" fill=\"#162443\">Les quatre croisements du dossier</text>\n<rect x=\"16\" y=\"44\" width=\"608\" height=\"46\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"320\" y=\"63\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#162443\">Trois sources qui doivent raconter la même histoire</text>\n<text x=\"320\" y=\"83\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">ce que le client dit, ce que les pièces montrent, ce que le projet suppose</text>\n<g font-size=\"14\" fill=\"#8A95A8\" text-anchor=\"middle\">\n<text x=\"172\" y=\"110\">Ce que le client annonce</text>\n<text x=\"487\" y=\"110\">Ce qui doit le confirmer</text>\n</g>\n<g fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\">\n<rect x=\"54\" y=\"120\" width=\"236\" height=\"40\" rx=\"8\"/>\n<rect x=\"54\" y=\"166\" width=\"236\" height=\"40\" rx=\"8\"/>\n<rect x=\"54\" y=\"212\" width=\"236\" height=\"40\" rx=\"8\"/>\n<rect x=\"54\" y=\"258\" width=\"236\" height=\"40\" rx=\"8\"/>\n</g>\n<g fill=\"#F5EDD8\" stroke=\"#C5A55A\" stroke-width=\"2\">\n<rect x=\"350\" y=\"120\" width=\"274\" height=\"40\" rx=\"8\"/>\n<rect x=\"350\" y=\"166\" width=\"274\" height=\"40\" rx=\"8\"/>\n<rect x=\"350\" y=\"212\" width=\"274\" height=\"40\" rx=\"8\"/>\n<rect x=\"350\" y=\"258\" width=\"274\" height=\"40\" rx=\"8\"/>\n</g>\n<g fill=\"#162443\">\n<circle cx=\"32\" cy=\"140\" r=\"13\"/>\n<circle cx=\"32\" cy=\"186\" r=\"13\"/>\n<circle cx=\"32\" cy=\"232\" r=\"13\"/>\n<circle cx=\"32\" cy=\"278\" r=\"13\"/>\n</g>\n<g font-size=\"13\" font-weight=\"700\" fill=\"#FFFFFF\" text-anchor=\"middle\">\n<text x=\"32\" y=\"145\">1</text>\n<text x=\"32\" y=\"191\">2</text>\n<text x=\"32\" y=\"237\">3</text>\n<text x=\"32\" y=\"283\">4</text>\n</g>\n<g font-size=\"15\" fill=\"#162443\" text-anchor=\"middle\">\n<text x=\"172\" y=\"145\">Revenus déclarés</text>\n<text x=\"172\" y=\"191\">Montant à investir</text>\n<text x=\"172\" y=\"237\">Horizon et objectif</text>\n<text x=\"172\" y=\"283\">Risque déclaré</text>\n<text x=\"487\" y=\"145\">Avis d’imposition</text>\n<text x=\"487\" y=\"191\">Patrimoine et origine des fonds</text>\n<text x=\"487\" y=\"237\">Besoin de liquidité</text>\n<text x=\"487\" y=\"283\">Expérience réelle</text>\n</g>\n<g font-size=\"14\" font-weight=\"700\" fill=\"#C5A55A\" text-anchor=\"middle\">\n<text x=\"320\" y=\"145\">contre</text>\n<text x=\"320\" y=\"191\">contre</text>\n<text x=\"320\" y=\"237\">contre</text>\n<text x=\"320\" y=\"283\">contre</text>\n</g>\n<rect x=\"16\" y=\"306\" width=\"608\" height=\"44\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#C5A55A\" stroke-width=\"2\"/>\n<text x=\"320\" y=\"325\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\" fill=\"#162443\">Un écart se questionne et se documente : version corrigée, date, source, pièce.</text>\n<text x=\"320\" y=\"345\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Corriger seul, c’est fabriquer le dossier.</text>\n</svg>","legende":"Ce que le client dit, ce que les pièces montrent et ce que le projet suppose doivent raconter la même histoire. Un écart se questionne avec neutralité et se documente : version corrigée, date, source, pièce."}]$academy_deck$::jsonb;
  select coalesce(jsonb_agg(s), '[]'::jsonb) into v_conserves
    from jsonb_array_elements(coalesce((select schemas from public.academy_module_versions where id = v_ver), '[]'::jsonb)) s
   where not exists (select 1 from jsonb_array_elements(v_nouveaux) x where x ->> 'cle' = s ->> 'cle');
  update public.academy_module_versions set schemas = v_conserves || v_nouveaux, updated_at = now() where id = v_ver;
  -- Figures : posee sur l exercice existant (ordre, type) qui n en a pas ; au dela du maximum, exercice nouveau.
  select coalesce(max(ordre), 0) into v_max from public.academy_items where version_id = v_ver;
  if v_max >= 5 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"quatre_croisements"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 5 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 5, $academy_deck$choix$academy_deck$, $academy_deck$Détecter les incohérences$academy_deck$, 2, $academy_deck${"enonce":"Cas fictif. Le questionnaire de Monsieur Lecoq indique 60 000 euros de revenus annuels, son avis d'imposition 38 000 euros. Il veut placer 250 000 euros d'économies. Quelle est la bonne suite ?","choix":["Corriger le questionnaire pour l'aligner sur l'avis d'imposition","Ignorer l'écart, il ne change pas la recommandation","Questionner le client sur l'écart et sur l'origine des 250 000 euros, puis noter la réponse et la pièce","Remonter immédiatement le dossier pour déclaration à Tracfin"],"figure":{"ref":"quatre_croisements"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":2}$academy_deck$::jsonb, $academy_deck$Une incohérence se questionne avec neutralité et se documente ; corriger seul revient à fabriquer le dossier, escalader avant d'interroger le client est prématuré.$academy_deck$);
  end if;
  if v_max >= 41 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"trois_niveaux"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 41 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 41, $academy_deck$choix$academy_deck$, $academy_deck$Examen renforcé$academy_deck$, 2, $academy_deck${"enonce":"Sur le schéma, cas fictif : un client remet toutes ses pièces sauf son justificatif de domicile, périmé depuis trois mois, qu’il promet d’envoyer jeudi. À quel niveau se traite ce dossier ?","choix":["Au premier : pièce manquante ou écart explicable, réglé avec le client","Au deuxième : une pièce manquante ouvre toujours un examen renforcé","Au troisième : une pièce périmée vaut soupçon et se remonte par écrit","À aucun : l’opération peut se faire, la pièce la régularisera jeudi"],"figure":{"ref":"trois_niveaux"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":0}$academy_deck$::jsonb, $academy_deck$Le premier niveau du schéma couvre la pièce manquante ou l’écart explicable ; l’examen renforcé vise l’opération inhabituelle et le soupçon porte sur l’origine des sommes. La pièce reste attendue : produite après l’opération, elle ne régulariserait rien.$academy_deck$);
  end if;
  if v_max >= 42 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"quatre_croisements"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 42 and type = $academy_deck$multi$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 42, $academy_deck$multi$academy_deck$, $academy_deck$Détecter les incohérences$academy_deck$, 3, $academy_deck${"enonce":"Sur le schéma des croisements, cochez tout ce que sa lecture permet d’affirmer.","choix":["Les trois sources du haut sont ce que le client dit, ce que les pièces montrent, ce que le projet suppose","Chaque ligne oppose ce que le client annonce à ce qui doit le confirmer","Un écart se note avec sa version corrigée, sa date, sa source et sa pièce","Une ligne qui ne colle pas suffit à faire une déclaration de soupçon","Le conseiller aligne lui même la fiche sur la pièce pour que les deux colonnes concordent","Les frais du contrat proposé font partie des lignes à croiser"],"figure":{"ref":"quatre_croisements"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"indices":[0,1,2]}$academy_deck$::jsonb, $academy_deck$Les trois sources se croisent ligne par ligne et l’écart se documente. Un écart n’est pas un soupçon, corriger seul revient à fabriquer le dossier, et les frais du contrat ne font pas partie des croisements.$academy_deck$);
  end if;
  if v_max >= 43 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"quatre_croisements"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 43 and type = $academy_deck$trou_choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 43, $academy_deck$trou_choix$academy_deck$, $academy_deck$Détecter les incohérences$academy_deck$, 1, $academy_deck${"phrase":"Sur le schéma, la troisième ligne croise l’horizon et l’objectif annoncés avec ___.","choix":["le besoin de liquidité","le patrimoine déclaré","l’expérience réelle du client","l’avis d’imposition"],"figure":{"ref":"quatre_croisements"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":0}$academy_deck$::jsonb, $academy_deck$Horizon et objectif contre besoin de liquidité : un projet daté proche contredit un horizon long, et aucune enveloppe peu disponible ne se recommande tant que l’écart n’est pas levé.$academy_deck$);
  end if;
end
$schemas_qualite_du_dossier$;
